code.cpp:
class Solution {
    void countWords(const string& s, unordered_map<string, int>& count) {
        stringstream ss(s);
        string word;
        while (ss >> word) {
            count[word]++;
        }
    }
public:
    vector<string> uncommonFromSentences(string s1, string s2) {
        unordered_map<string, int> count;
        countWords(s1, count);
        countWords(s2, count);

        vector<string> result;
        for (auto& [word, freq] : count) {
            if (freq == 1) {
                result.push_back(word);
            }
        }
        return result;
    }
};
